{"implementation":"def solve(case):
    payload = case.get("payload")
    if payload is None:
        raise ValueError("Missing payload")
    segments = payload.get("segments")
    budget = payload.get("budget")
    if segments is None or budget is None:
        raise ValueError("Missing required fields")
    n = len(segments)
    for seg in segments:
        if not all(k in seg for k in ("name","importance","minimum","capacity")):
            raise ValueError("Segment missing required field")
    total_min = sum(seg["minimum"] for seg in segments)
    total_cap = sum(seg["capacity"] for seg in segments)
    if budget < total_min or budget > total_cap:
        raise ValueError("Budget out of feasible range")
    allocated = [seg["minimum"] for seg in segments]
    remaining = budget - total_min
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i, seg in enumerate(segments):
            if allocated[i] >= seg["capacity"]:
                continue
            ratio = seg["importance"] / (allocated[i] + 1)
            if ratio > best_ratio or (ratio == best_ratio and i < best_idx):
                best_ratio = ratio
                best_idx = i
        if best_idx == -1:
            raise ValueError("Unable to allocate remaining budget")
        allocated[best_idx] += 1
        remaining -= 1
    allocations = {}
    for i, seg in enumerate(segments):
        allocations[seg["name"]] = allocated[i]
    name_mapping = [seg["name"] for seg in segments]
    total = sum(allocated)
    return {
        "allocations": allocations,
        "name_mapping": name_mapping,
        "total": total
    }"}
